  updateFilterSelect('filter-username', usernames);

  // فلتر الصفحة
  const pageNames = [...new Set(allUsers.map(u => u.pageName).filter(Boolean))].sort();
  updateFilterSelect('filter-pagename', pageNames);

  // فلتر المشرف
  const supervisors = [...new Set(allUsers.map(u => u.supervisor).filter(Boolean))].sort();
  updateFilterSelect('filter-supervisor', supervisors);
